  error: null,
};

// Async Thunks
export const fetchLibrary = createAsyncThunk(
  "library/fetchLibrary",
  async (uid: string, { rejectWithValue }) => {
    try {
      const items = mockLibrary.getLibrary(uid);
      return items;
    } catch (err: any) {
      return rejectWithValue(err.message);
    }
  }
