export default function BookDetails() {
  const { id } = useParams() as { id: string };
  const router = useRouter();
  const dispatch = useAppDispatch();

  const { user } = useAppSelector((state) => state.auth);
  const { savedBooks, loading: libraryLoading } = useAppSelector(
    (state) => state.library
  );

  const [book, setBook] = useState<Book | null>(null);
  const [loading, setLoading] = useState(true);

  const isSaved = savedBooks.some((b) => b.id === id);

  // Fetch book details
  useEffect(() => {
    const fetchBookDetails = async () => {
      try {
        const res = await fetch(
          `https://us-central1-summaristt.cloudfunctions.net/getBook?id=${id}`
        );
        const data = await res.json();
        setBook(data);
      } catch (err) {
        console.error("Error fetching book details:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchBookDetails();
  }, [id]);

  // Fetch user library if user is logged in
  useEffect(() => {
    if (user?.uid) {
      dispatch(fetchLibrary(user.uid));
    }
  }, [user, dispatch]);

  const handleLibraryAction = () => {
    if (!user) {
      dispatch(openAuthModal());
      return;
    }

    if (!book) return;

    if (isSaved) {
      dispatch(removeBookFromLibrary({ uid: user.uid, id: book.id }));
    } else {
      dispatch(
        saveBookToLibrary({
          uid: user.uid,
          book: {
            id: book.id,
            title: book.title,
            author: book.author,
            imageLink: book.imageLink,
          },
        })
      );
    }
  };

  const handleReadOrListen = () => {
    if (!user) {
      dispatch(openAuthModal());
      return;
    }

    if (!book) return;

    const subStatus = mockBilling.getSubscriptionStatus(user.uid);
    const hasPremiumAccess = subStatus !== "basic";

    if (book.subscriptionRequired && !hasPremiumAccess && !user.isGuest) {
      // Premium book, user is not subscribed and is not a guest -> sales page
      router.push("/choose-plan");
    } else {
      // Free book, user is subscribed, or user is guest -> player page
      router.push(`/player/${book.id}`);
    }
  };

  if (loading) {
    return (
      <div className="w-full flex flex-col gap-10 animate-pulse">
        <div className="flex flex-col lg:flex-row gap-10">
          <div className="w-[180px] h-[270px] bg-gray-200 rounded-xl shrink-0 mx-auto lg:mx-0"></div>
          <div className="flex-1 flex flex-col justify-center gap-4">
            <div className="h-8 bg-gray-200 rounded w-2/3"></div>
            <div className="h-5 bg-gray-200 rounded w-1/4"></div>
            <div className="h-5 bg-gray-200 rounded w-1/3"></div>
            <div className="flex gap-4 mt-4">
              <div className="h-12 bg-gray-200 rounded-lg w-28"></div>
              <div className="h-12 bg-gray-200 rounded-lg w-28"></div>
            </div>
          </div>
        </div>
        <div className="flex flex-col gap-4">
          <div className="h-6 bg-gray-200 rounded w-1/4"></div>
          <div className="h-4 bg-gray-200 rounded w-full"></div>
          <div className="h-4 bg-gray-200 rounded w-full"></div>
          <div className="h-4 bg-gray-200 rounded w-3/4"></div>
        </div>
      </div>
    );
  }

  if (!book) {
    return (
      <div className="w-full text-center py-20 text-gray-500">
        Book details could not be found.
      </div>
    );
  }

  // Mock metadata if not present
  const rating = book.averageRating || 4.5;
  const ratingCount = book.totalRating || 120;
  const duration = "15 min"; // Mock duration
  const keyIdeas = book.keyIdeas || "10 key ideas";
  const type = book.type || "Audio & Text";

  return (
    <div className="w-full flex flex-col gap-10">
      {/* Top Section: Cover & CTA */}
      <div className="flex flex-col lg:flex-row gap-8 lg:gap-12 items-center lg:items-stretch">
        {/* Image */}
        <div className="relative w-[180px] h-[270px] lg:w-[220px] lg:h-[330px] shadow-2xl rounded-2xl overflow-hidden shrink-0 bg-gray-50 border border-gray-100">
          <Image
            src={book.imageLink}
            alt={book.title}
            fill
            className="object-cover"
            priority
          />
        </div>

        {/* Text Details & Buttons */}
        <div className="flex-1 flex flex-col justify-center text-center lg:text-left">
          <h1 className="text-2xl lg:text-4xl font-black text-[#032b41] mb-2 leading-tight">
            {book.title}
          </h1>
          <p className="text-base font-bold text-gray-700 mb-2">By {book.author}</p>
          <p className="text-sm font-light text-gray-500 mb-6 max-w-[600px] leading-relaxed">
            {book.subTitle}
          </p>

          {/* Key details tags */}
          <div className="flex flex-wrap items-center justify-center lg:justify-start gap-4 mb-8 text-xs font-semibold text-gray-600 border-y border-gray-150 py-4">
            <div className="flex items-center gap-1.5">
              <AiOutlineStar className="text-amber-500" size={16} />
              <span>{rating.toFixed(1)}</span>
              <span className="text-gray-400">({ratingCount} ratings)</span>
            </div>
            <span className="text-gray-250">|</span>
            <div className="flex items-center gap-1.5">
              <AiOutlineClockCircle size={16} className="text-gray-500" />
              <span>{duration}</span>
            </div>
            <span className="text-gray-250">|</span>
            <div className="flex items-center gap-1.5">
              <AiOutlineAudio size={16} className="text-gray-500" />
              <span>{type}</span>
            </div>
          </div>

          {/* Action CTA Buttons */}
          <div className="flex flex-wrap items-center justify-center lg:justify-start gap-4">
            <button
              onClick={handleReadOrListen}
              className="flex items-center justify-center gap-3 bg-[#032b41] hover:bg-[#04334d] text-white font-bold py-3.5 px-8 rounded-xl text-sm transition-all duration-200 select-none shadow-md shadow-[#032b41]/10"
            >
              <AiOutlineFileText size={18} />
              <span>Read</span>
            </button>

            <button
              onClick={handleReadOrListen}
              className="flex items-center justify-center gap-3 bg-[#032b41] hover:bg-[#04334d] text-white font-bold py-3.5 px-8 rounded-xl text-sm transition-all duration-200 select-none shadow-md shadow-[#032b41]/10"
            >
              <BiVolumeFull size={18} />
              <span>Listen</span>
            </button>

            {/* Library toggle Button */}
            <button
              onClick={handleLibraryAction}
              disabled={libraryLoading}
              className={`flex items-center justify-center gap-2.5 font-bold py-3.5 px-6 rounded-xl text-sm transition-all duration-200 select-none border ${
                isSaved
                  ? "border-red-200 bg-red-50 text-red-600 hover:bg-red-100/50 hover:border-red-300"
                  : "border-gray-200 hover:bg-gray-50 text-[#032b41]"
              }`}
            >
              {isSaved ? (
                <>
                  <BsBookmarkDash size={16} />
                  <span>Remove from Library</span>
                </>
              ) : (
                <>
                  <BsBookmarkPlusFill size={16} className="text-[#3ac27c]" />
                  <span>Save to Library</span>
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Bottom Section: Summary & Author */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10 mt-6 border-t border-gray-100 pt-10">
        {/* About Book */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div>
            <h3 className="text-xl font-bold text-[#032b41] mb-3">What&apos;s inside?</h3>
            <p className="text-sm font-semibold text-gray-500 mb-4">{keyIdeas}</p>
            <div className="h-1.5 w-16 bg-[#2bd97c] rounded-full"></div>
          </div>
          <div className="flex flex-col gap-4 text-sm text-gray-600 font-light leading-relaxed">
            <h4 className="font-bold text-base text-[#032b41]">Book Description</h4>
            <p className="whitespace-pre-line">
              {book.bookDescription ||
                "This book provides actionable insights and powerful principles to transform your perspective. Discover the core values, key decisions, and habits that separate high-performers from the rest of the world."}
            </p>
          </div>
        </div>

        {/* About Author */}
        <div className="bg-[#f7faf9] rounded-2xl p-6 border border-gray-100 flex flex-col gap-4">
          <h3 className="text-lg font-bold text-[#032b41]">About the Author</h3>
          <p className="text-xs text-gray-400 font-semibold uppercase tracking-wider">
            Featured writer
          </p>
          <p className="text-sm text-gray-600 font-light leading-relaxed whitespace-pre-line">
            {book.authorDescription ||
              `${book.author} is a highly acclaimed author and subject matter expert. Their work focus on personal development, strategic decision-making, and structural transformation.`}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useAppDispatch } from "@/redux/store";
import { setIsPlaying as setReduxIsPlaying, setCurrentTime as setReduxCurrentTime, setDuration as setReduxDuration } from "@/redux/playerSlice";

export function useAudioPlayer(audioUrl: string | undefined, onEndedCallback?: () => void) {
  const dispatch = useAppDispatch();
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackRate, setPlaybackRate] = useState(1.0);
  const [volume, setVolume] = useState(1.0);
  const [isMuted, setIsMuted] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Initialize Audio
  useEffect(() => {
    if (!audioUrl) return;

    const audio = new Audio(audioUrl);
    audioRef.current = audio;

    // Event listeners
    const onLoadedMetadata = () => {
      setDuration(audio.duration);
      dispatch(setReduxDuration(audio.duration));
    };

    const onTimeUpdate = () => {
      setCurrentTime(audio.currentTime);
      dispatch(setReduxCurrentTime(audio.currentTime));
    };

    const onEnded = () => {
      setIsPlaying(false);
      dispatch(setReduxIsPlaying(false));
      if (onEndedCallback) {
        onEndedCallback();
      }
    };

    audio.addEventListener("loadedmetadata", onLoadedMetadata);
    audio.addEventListener("timeupdate", onTimeUpdate);
    audio.addEventListener("ended", onEnded);

    // Set initial values
    audio.playbackRate = playbackRate;
    audio.volume = isMuted ? 0 : volume;

    return () => {
      audio.pause();
      audio.removeEventListener("loadedmetadata", onLoadedMetadata);
      audio.removeEventListener("timeupdate", onTimeUpdate);
      audio.removeEventListener("ended", onEnded);
      audioRef.current = null;
    };
  }, [audioUrl, dispatch]);

  // Sync controls with audio ref
  const play = () => {
    if (audioRef.current) {
      audioRef.current.play();
      setIsPlaying(true);
      dispatch(setReduxIsPlaying(true));
    }
  };

  const pause = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setIsPlaying(false);
      dispatch(setReduxIsPlaying(false));
    }
  };

  const togglePlay = () => {
    if (isPlaying) {
      pause();
    } else {
      play();
    }
  };

  const seek = (time: number) => {
    if (audioRef.current) {
      audioRef.current.currentTime = time;
      setCurrentTime(time);
      dispatch(setReduxCurrentTime(time));
    }
  };

  const changeSpeed = (rate: number) => {
    if (audioRef.current) {
      audioRef.current.playbackRate = rate;
    }
    setPlaybackRate(rate);
  };

  const skipForward = () => {
    if (audioRef.current) {
      const newTime = Math.min(audioRef.current.currentTime + 15, duration);
      seek(newTime);
    }
  };

  const skipBackward = () => {
    if (audioRef.current) {
      const newTime = Math.max(audioRef.current.currentTime - 15, 0);
      seek(newTime);
    }
  };

  const changeVolume = (vol: number) => {
    if (audioRef.current) {
      audioRef.current.volume = vol;
    }
    setVolume(vol);
    if (vol > 0) setIsMuted(false);
  };

  const toggleMute = () => {
    if (audioRef.current) {
      audioRef.current.volume = !isMuted ? 0 : volume;
    }
    setIsMuted(!isMuted);
  };

  return {
    isPlaying,
    currentTime,
    duration,
    playbackRate,
    volume,
    isMuted,
    play,
    pause,
    togglePlay,
    seek,
    changeSpeed,
    skipForward,
    skipBackward,
    changeVolume,
    toggleMute,
  };
}

"use client";

import React, { useState, useEffect } from "react";
import Image from "next/image";
import { useParams, useRouter } from "next/navigation";
import { useAppDispatch, useAppSelector } from "@/redux/store";
import { openAuthModal } from "@/redux/authSlice";
import { markBookFinished, fetchLibrary } from "@/redux/librarySlice";
import { setBook } from "@/redux/playerSlice";
import { useAudioPlayer } from "@/hooks/useAudioPlayer";
import { Book } from "@/redux/playerSlice";
import confetti from "canvas-confetti";

import {
  AiOutlinePlayCircle,
  AiOutlinePauseCircle,
  AiOutlineUndo,
  AiOutlineRedo,
  AiOutlineLoading3Quarters,
} from "react-icons/ai";

import {
  BiVolumeFull,
  BiVolumeMute,
} from "react-icons/bi";

export default function AudioPlayerPage() {
  const { id } = useParams() as { id: string };
  const router = useRouter();
  const dispatch = useAppDispatch();

  const { user } = useAppSelector((state) => state.auth);
  const [bookDetails, setBookDetails] = useState<Book | null>(null);
  const [loading, setLoading] = useState(true);
  const [speedDropdownOpen, setSpeedDropdownOpen] = useState(false);

  // Fetch book details
  useEffect(() => {
    const fetchBook = async () => {
      try {
        const res = await fetch(
          `https://us-central1-summaristt.cloudfunctions.net/getBook?id=${id}`
        );
        const data = await res.json();
        setBookDetails(data);
        dispatch(setBook(data));
      } catch (err) {
        console.error("Error fetching book details:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchBook();

    return () => {
      dispatch(setBook(null));
    };
  }, [id, dispatch]);

  // Fetch library when loaded
  useEffect(() => {
    if (user?.uid) {
      dispatch(fetchLibrary(user.uid));
    }
  }, [user, dispatch]);

  // Callback when audio finishes playing
  const handleAudioEnded = () => {
    if (user?.uid) {
      dispatch(markBookFinished({ uid: user.uid, id }));

      // Trigger confetti!
      confetti({
        particleCount: 150,
        spread: 80,
        origin: { y: 0.6 },
        colors: ["#2bd97c", "#032b41", "#fb9b50", "#0365f2"],
      });

      alert("Congratulations! You've finished this book summary!");
    }
  };

  const {
    isPlaying,
    currentTime,
    duration,
    playbackRate,
    volume,
    isMuted,
    togglePlay,
    seek,
    changeSpeed,
    skipForward,
    skipBackward,
    changeVolume,
    toggleMute,
  } = useAudioPlayer(bookDetails?.audioLink, handleAudioEnded);

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds < 10 ? "0" : ""}${seconds}`;
  };

  if (loading) {
    return (
      <div className="w-full flex flex-col justify-center items-center py-20 text-gray-500 gap-4">
        <AiOutlineLoading3Quarters size={40} className="animate-spin text-[#3ac27c]" />
        <span className="font-semibold text-sm">Loading audio player...</span>
      </div>
    );
  }

  if (!bookDetails) {
    return (
      <div className="w-full text-center py-20 text-gray-500">
        Audio content could not be loaded.
      </div>
    );
  }

  const speedOptions = [0.75, 1.0, 1.25, 1.5, 2.0];

  return (
    <div className="w-full flex flex-col gap-8">
      {/* Upper Section: Book description / metadata */}
      <div className="flex flex-col md:flex-row gap-6 border-b border-gray-100 pb-8 items-center md:items-start text-center md:text-left">
        <div className="relative w-[100px] h-[150px] shadow-lg rounded-xl overflow-hidden shrink-0 bg-gray-50 border border-gray-100">
          <Image
            src={bookDetails.imageLink}
            alt={bookDetails.title}
            fill
            className="object-cover"
          />
        </div>
        <div className="flex flex-col justify-center gap-2">
          <h1 className="text-xl md:text-2xl font-black text-[#032b41] leading-tight">
            {bookDetails.title}
          </h1>
          <p className="text-sm font-semibold text-[#3ac27c]">{bookDetails.author}</p>
          <p className="text-xs text-gray-400 font-light max-w-[500px]">
            {bookDetails.subTitle}
          </p>
        </div>
      </div>

      {/* Main Interactive Audio Player UI */}
      <div className="bg-[#032b41] text-white rounded-2xl p-6 md:p-8 flex flex-col items-center gap-6 shadow-xl relative overflow-hidden select-none">
        {/* Subtle decorative background glow */}
        <div className="absolute -top-12 -left-12 w-36 h-36 rounded-full bg-[#3ac27c]/10 blur-xl"></div>
        <div className="absolute -bottom-12 -right-12 w-36 h-36 rounded-full bg-[#0365f2]/10 blur-xl"></div>

        {/* Controls Row */}
        <div className="flex items-center gap-8 z-10">
          {/* Skip Backward Button */}
          <button
            onClick={skipBackward}
            className="text-gray-400 hover:text-white transition-colors"
            title="Rewind 15 seconds"
          >
            <AiOutlineUndo size={28} />
          </button>

          {/* Main Play/Pause Button */}
          <button
            onClick={togglePlay}
            className="text-[#2bd97c] hover:scale-105 transition-transform"
            title={isPlaying ? "Pause" : "Play"}
          >
            {isPlaying ? (
              <AiOutlinePauseCircle size={68} />
            ) : (
              <AiOutlinePlayCircle size={68} />
            )}
          </button>

          {/* Skip Forward Button */}
          <button
            onClick={skipForward}
            className="text-gray-400 hover:text-white transition-colors"
            title="Fast-forward 15 seconds"
          >
            <AiOutlineRedo size={28} />
          </button>
        </div>

        {/* Timeline Slider Progress Row */}
        <div className="w-full flex items-center gap-4 z-10 text-xs font-semibold text-gray-300">
          <span>{formatTime(currentTime)}</span>
          <input
            type="range"
            min={0}
            max={duration || 100}
            value={currentTime}
            onChange={(e) => seek(parseFloat(e.target.value))}
            className="flex-1 h-1.5 rounded-lg appearance-none cursor-pointer outline-none bg-gray-600 accent-[#2bd97c]"
          />
          <span>{formatTime(duration)}</span>
        </div>

        {/* Bottom Volume/Speed Controls Row */}
        <div className="w-full flex items-center justify-between border-t border-white/10 pt-4 z-10 text-sm">
          {/* Speed Selection */}
          <div className="relative">
            <button
              onClick={() => setSpeedDropdownOpen(!speedDropdownOpen)}
              className="text-gray-300 hover:text-white font-bold py-1.5 px-3 bg-white/5 rounded-lg border border-white/10 hover:bg-white/10 transition-colors"
            >
              Speed: {playbackRate}x
            </button>
            {speedDropdownOpen && (
              <div className="absolute bottom-full mb-2 left-0 bg-[#04334d] border border-white/10 rounded-lg shadow-xl overflow-hidden flex flex-col divide-y divide-white/5">
                {speedOptions.map((opt) => (
                  <button
                    key={opt}
                    onClick={() => {
                      changeSpeed(opt);
                      setSpeedDropdownOpen(false);
                    }}
                    className={`py-2 px-5 text-xs text-left hover:bg-white/10 transition-colors ${
                      playbackRate === opt ? "text-[#2bd97c] font-bold" : "text-white"
                    }`}
                  >
                    {opt.toFixed(2)}x
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Volume Control */}
          <div className="flex items-center gap-2">
            <button
              onClick={toggleMute}
              className="text-gray-300 hover:text-white transition-colors"
            >
              {isMuted || volume === 0 ? (
                <BiVolumeMute size={20} className="text-red-400" />
              ) : (
                <BiVolumeFull size={20} />
              )}
            </button>
            <input
              type="range"
              min={0}
              max={1}
              step={0.1}
              value={isMuted ? 0 : volume}
              onChange={(e) => changeVolume(parseFloat(e.target.value))}
              className="w-20 h-1 rounded-lg appearance-none cursor-pointer outline-none bg-gray-600 accent-white"
            />
          </div>
        </div>
      </div>

      {/* Summary Text Paragraphs */}
      <div className="flex flex-col gap-4 border-t border-gray-150 pt-8 mt-4">
        <h2 className="text-xl font-bold text-[#032b41]">Summary</h2>
        <div className="whitespace-pre-line text-sm text-gray-600 font-light leading-relaxed">
          {bookDetails.summary}
        </div>
      </div>
    </div>
  );
}

"use client";

